"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[721],{6135:function(e,a,t){t.d(a,{EmailLink:function(){return r}});var o=t(7437),i=t(3548),n=t(8178);function r(e){let{ctaLocation:a,className:t,children:r}=e;return(0,o.jsx)("a",{href:"mailto:".concat(n.B6.email),className:t,onClick:()=>(0,i.te)(a),children:null!=r?r:n.B6.email})}},3548:function(e,a,t){function o(e){window.dataLayer=window.dataLayer||[],window.dataLayer.push(e)}function i(e){o({event:"form_submit",form_name:e})}function n(e){o({event:"form_success",form_name:e})}function r(e){o({event:"email_click",cta_location:e})}function s(e,a){o({event:"center_click",center_slug:e,country:a})}function c(e){o({event:"find_center_click",cta_location:e})}function l(){o({event:"scroll_75"})}t.d(a,{Io:function(){return l},_f:function(){return s},fd:function(){return i},m$:function(){return c},n3:function(){return n},te:function(){return r}})},8178:function(e,a,t){t.d(a,{m9:function(){return s},cx:function(){return n},B6:function(){return i},hD:function(){return r}});let o=[{slug:"palm-beach-florida",name:"Animal Alliance Radiation Oncology",localName:"Animal Alliance Radiation Oncology \xb7 Palm Beach",city:"Palm Beach",country:"United States",countryCode:"US",countrySlug:"united-states",type:"radiation-oncology",status:"operating",featured:!0,website:"https://aaradonc.com",socialProfiles:["https://www.instagram.com/aaradonc/"],mapPoint:{lat:26.6827,lng:-80.2508},logo:{src:"/images/centers/logos/palm-beach-florida.svg",width:221,height:60},logoOnDark:{src:"/images/centers/logos/palm-beach-florida-white.svg",width:221,height:60},services:["radiotherapy","oncology-consultation"],address:{street:"12993 Southern Blvd, Suite A",locality:"Loxahatchee",region:"FL",postalCode:"33470",country:"United States",note:"The center serves the Palm Beach area from Loxahatchee, in Palm Beach County."},phone:"(561) 557-2565",phoneE164:"+15615572565",email:"info@aaradonc.com",openingHours:"Monday to Friday, 8:00 AM – 5:00 PM",openingHoursSpec:["Mo-Fr 08:00-17:00"],geo:{latitude:26.6826731,longitude:-80.2507762},summary:"The only center in Florida dedicated entirely to veterinary radiation oncology.",description:["Animal Alliance Radiation Oncology is Orbit’s center in the United States, open and treating patients in Palm Beach County, Florida. In the center’s own words, it is the only center in Florida dedicated 100% to radiation oncology — not a general practice with a linear accelerator attached, but a facility built around one discipline.","Treatment is delivered on a Varian TrueBeam linear accelerator, the same platform used in human cancer centers, with a board-certified radiation oncologist on site. Three protocol families are offered: CFRT for curative and adjuvant intent, SRS and SRT for stereotactic treatment of tumours that need sub-millimetre precision, and palliative radiation where the goal is comfort rather than long-term control.","That range matters clinically. Stereotactic treatment concentrates a large dose into very few sessions, which is what makes it possible to treat some brain, nasal and bone tumours that a conventional course would not reach as cleanly — and it means fewer anaesthetic events for the patient.","The center works with referring veterinarians across Florida and returns every patient to the referring practice; it does not take over the animal’s general care. It applies the unified medical, technical and safety standards used at every Orbit center, and it is the point at which four decades of Florida radiation oncology experience — through 21st Century Oncology and Advocate — reaches companion animals."],distinction:"The only center 100% dedicated to Radiation Oncology in Florida.",todo:["Exterior, bunker and Varian TrueBeam photography.","Confirm the opening date, for the corporate track record.","Confirm how the center should be named in Orbit’s own directory — its site uses “Animal Alliance Radiation Oncology \xb7 Palm Beach”."]},{slug:"sao-paulo-brazil",name:"Vet Radioterapia SP",localName:"Vet Radioterapia S\xe3o Paulo",city:"S\xe3o Paulo",country:"Brazil",countryCode:"BR",countrySlug:"brazil",type:"radiation-oncology",status:"operating",website:"https://vetradioterapiasp.com.br",mapPoint:{lat:-23.5329,lng:-46.7918},logo:{src:"/images/centers/logos/sao-paulo-brazil.webp",width:101,height:96},services:["radiotherapy","oncology-consultation"],address:{street:"Av. Jo\xe3o Batista, 1081 — Centro",locality:"Osasco",region:"S\xe3o Paulo",postalCode:null,country:"Brazil",note:"The center serves Greater S\xe3o Paulo from Osasco, in the S\xe3o Paulo metropolitan area."},phone:"+55 11 99372-3293",phoneE164:"+5511993723293",email:"info@vetradioterapiasp.com.br",openingHours:null,openingHoursSpec:null,geo:null,summary:"3D veterinary radiotherapy in Osasco, S\xe3o Paulo.",description:["Vet Radioterapia S\xe3o Paulo delivers 3D conformal radiotherapy for dogs and cats across Greater S\xe3o Paulo. The center serves the metropolitan area from Osasco, and works with referring veterinarians throughout the region.","Radiotherapy at the center is planned individually for each patient. Imaging is used to map the tumour and the surrounding healthy tissue, and the treatment plan is built to concentrate dose on the target while limiting what reaches the tissue around it. Treatment itself is non-invasive: the animal is positioned, the accelerator delivers the planned dose, and the patient goes home the same day.","The center is staffed by a multidisciplinary team of veterinarians, oncologists, radiotherapy specialists and technicians, and follows the unified medical, technical and safety standards applied across every Orbit center.","Referring veterinarians keep their patients: the center works alongside the primary veterinarian, who continues to manage the animal’s general care throughout and after the course of treatment."],distinction:null,todo:["Opening hours.","Verified GPS coordinates.","Postal code (CEP) for the structured address.","Facility and linear accelerator photography."]},{slug:"rio-de-janeiro-brazil",name:"Vet Radioterapia RJ",localName:"Vet Radioterapia Rio de Janeiro",city:"Rio de Janeiro",country:"Brazil",countryCode:"BR",countrySlug:"brazil",type:"radiation-oncology",status:"operating",website:"https://vetradioterapiarj.com.br",mapPoint:{lat:-23.0004,lng:-43.3656},logo:{src:"/images/centers/logos/rio-de-janeiro-brazil.webp",width:498,height:96},services:["radiotherapy","oncology-consultation"],address:{street:"Av. das Am\xe9ricas, 505 — Loja A, Barra da Tijuca",locality:"Rio de Janeiro",region:"Rio de Janeiro",postalCode:null,country:"Brazil"},phone:"+55 21 99325-8793",phoneE164:"+5521993258793",email:"info@vetradioterapiarj.com.br",openingHours:null,openingHoursSpec:null,geo:null,summary:"The only 3D veterinary radiotherapy service in Rio de Janeiro.",description:["Vet Radioterapia Rio de Janeiro is, in the center’s own words, the only 3D veterinary radiotherapy service in Rio de Janeiro. It operates from Barra da Tijuca and treats dogs and cats referred from across the city and the wider state.","Each patient is planned individually. Imaging defines the tumour volume and the healthy structures nearby, and the plan is built to deliver the prescribed dose to the target while sparing as much surrounding tissue as the anatomy allows. Sessions are outpatient — the animal is positioned, treated, and returns home the same day.","The center is run by a multidisciplinary team combining veterinary oncology, radiation oncology and medical physics, and applies the same medical, technical and safety standards used across the Orbit network.","For referring veterinarians, the center functions as a specialist service rather than a change of provider: the primary veterinarian stays responsible for the animal’s overall care, and receives the treatment plan and follow-up information for the course."],distinction:"The only 3D veterinary radiotherapy service in Rio de Janeiro.",todo:["Opening hours.","Verified GPS coordinates.","Postal code (CEP) for the structured address.","Facility and linear accelerator photography."]},{slug:"belo-horizonte-brazil",name:"COV Belo Horizonte",localName:"Centro Oncol\xf3gico Veterin\xe1rio Belo Horizonte",city:"Belo Horizonte",country:"Brazil",countryCode:"BR",countrySlug:"brazil",type:"comprehensive",status:"operating",website:"https://covbelohorizonte.com.br",mapPoint:{lat:-19.9167,lng:-43.9345},logo:{src:"/images/centers/logos/belo-horizonte-brazil.svg",width:624,height:188},services:["oncology-consultation","cytology-histopathology","diagnostic-imaging","chemotherapy","oncologic-surgery","electrochemotherapy"],address:{street:"Av. Nossa Sra. do Carmo, 1275",locality:"Belo Horizonte",region:"Minas Gerais",postalCode:null,country:"Brazil"},phone:"+55 31 98328-4639",phoneE164:"+5531983284639",email:"info@covbelohorizonte.com.br",openingHours:null,openingHoursSpec:null,geo:null,summary:"Comprehensive veterinary cancer center in Belo Horizonte.",description:["The Centro Oncol\xf3gico Veterin\xe1rio Belo Horizonte is a comprehensive veterinary cancer center: diagnosis, staging and treatment happen under one roof rather than across several referrals.","The center offers oncology consultation, cytology and histopathology, diagnostic imaging, chemotherapy, oncologic surgery and electrochemotherapy. That combination means a case can move from first suspicion through biopsy and staging to a treatment plan without the owner having to assemble the pieces themselves.","Electrochemotherapy — a chemotherapy agent combined with controlled electrical pulses that increase its uptake by tumour cells — is available on site alongside conventional chemotherapy and surgery, and is one of the options considered for tumours that are accessible but difficult to remove completely.","Radiotherapy is not delivered at this location. Patients who need it are referred within the Orbit network, which operates dedicated radiotherapy centers in S\xe3o Paulo and Rio de Janeiro.","Like every Orbit center, Belo Horizonte follows unified medical, technical and safety standards, and works alongside referring veterinarians rather than replacing them."],distinction:null,todo:["Opening hours.","Verified GPS coordinates.","Postal code (CEP) for the structured address.","Confirm whether radiotherapy referrals go to S\xe3o Paulo, Rio de Janeiro, or both.","Facility photography."]},{slug:"goiania-brazil",name:"COV Goi\xe1s",localName:"Centro Oncol\xf3gico Veterin\xe1rio Goi\xe1s",city:"Goi\xe2nia",country:"Brazil",countryCode:"BR",countrySlug:"brazil",type:"comprehensive",status:"operating",website:"https://covgoias.com.br",mapPoint:{lat:-16.6869,lng:-49.2648},logo:{src:"/images/centers/logos/goiania-brazil.svg",width:1210,height:321},services:["oncology-consultation","cytology-histopathology","diagnostic-imaging","chemotherapy","oncologic-surgery","electrochemotherapy"],address:{street:"Rua C-235, n\xba 340, Jardim Am\xe9rica",locality:"Goi\xe2nia",region:"Goi\xe1s",postalCode:null,country:"Brazil"},phone:"+55 62 98333-3863",phoneE164:"+5562983333863",email:"covgoias@gmail.com",openingHours:null,openingHoursSpec:null,geo:null,summary:"Comprehensive veterinary cancer center in Goi\xe2nia.",description:["The Centro Oncol\xf3gico Veterin\xe1rio Goi\xe1s brings comprehensive veterinary cancer care to Goi\xe2nia and the surrounding region of central Brazil, where specialist oncology for companion animals has historically meant travelling to S\xe3o Paulo.","The center covers oncology consultation, cytology and histopathology, diagnostic imaging, chemotherapy, oncologic surgery and electrochemotherapy. Diagnosis and treatment are handled in the same place, which shortens the interval between a suspicious finding and a confirmed plan.","Cytology and histopathology on site matter more than they sound: most treatment decisions in veterinary oncology depend on knowing exactly which tumour type is present, and having that work done in-house removes a common source of delay.","Radiotherapy is not delivered at this location. Cases that call for it are referred within the Orbit network to the dedicated radiotherapy centers in S\xe3o Paulo and Rio de Janeiro.","The center applies the unified medical, technical and safety standards used across all Orbit centers, and works with referring veterinarians throughout Goi\xe1s."],distinction:null,todo:["Opening hours.","Verified GPS coordinates.","Postal code (CEP) for the structured address.","The center publishes a Gmail address (covgoias@gmail.com) rather than a domain address — confirm whether this is intended.","Facility photography."]},{slug:"guadalajara-mexico",name:"COV Guadalajara",localName:"Cl\xednica Oncol\xf3gica Veterinaria Guadalajara",city:"Guadalajara",country:"Mexico",countryCode:"MX",countrySlug:"mexico",type:"comprehensive-radiotherapy",status:"operating",website:"https://covguadalajara.mx",mapPoint:{lat:20.6597,lng:-103.3496},logo:{src:"/images/centers/logos/guadalajara-mexico.svg",width:997,height:350},services:["oncology-consultation","cytology-histopathology","diagnostic-imaging","chemotherapy","oncologic-surgery","electrochemotherapy","radiotherapy"],address:{street:"Avenida Jorge \xc1lvarez del Castillo 1595",locality:"Guadalajara",region:"Jalisco",postalCode:null,country:"Mexico"},phone:"+52 33 1155 1812",phoneE164:"+523311551812",email:"info@covguadalajara.mx",openingHours:null,openingHoursSpec:null,geo:null,summary:"The first clinic in Mexico specialising in veterinary radiotherapy, with full cancer care on site.",description:["The Cl\xednica Oncol\xf3gica Veterinaria Guadalajara describes itself as the first clinic in Mexico specialising in veterinary radiotherapy. It is a comprehensive cancer center: radiotherapy sits alongside the full diagnostic and treatment pathway rather than operating as a standalone service.","Available on site are oncology consultation, cytology and histopathology, veterinary CT, chemotherapy, oncologic surgery, electrochemotherapy and radiotherapy. Having veterinary CT in the same building as the accelerator matters directly: the same imaging used to diagnose and stage the tumour is the imaging used to plan the radiation dose.","That integration is what a comprehensive center is for. A patient can be examined, imaged, biopsied, staged and treated without moving between providers, and the team deciding between surgery, chemotherapy, electrochemotherapy and radiation is the team that will deliver whichever is chosen.","Radiotherapy sessions are outpatient. The center follows the unified medical, technical and safety standards applied across the Orbit network, and works with referring veterinarians across Jalisco and western Mexico."],distinction:"The first clinic in Mexico specialising in veterinary radiotherapy.",todo:["Opening hours.","Verified GPS coordinates.","The published address has no colonia or postal code — needed for a complete structured address.","Facility and linear accelerator photography."]},{slug:"mexico-city-mexico",name:"Pets Oncology",localName:"Pets Oncology",city:"Mexico City",neighbourhood:"Colonia Del Valle Centro",country:"Mexico",countryCode:"MX",countrySlug:"mexico",type:"comprehensive",status:"operating",website:"https://petsoncology.mx",mapPoint:{lat:19.3907,lng:-99.1656},mapNudge:{dx:-13,dy:6},logo:{src:"/images/centers/logos/mexico-city-mexico.svg",width:1115,height:256},services:["oncology-consultation","cytology-histopathology","diagnostic-imaging","chemotherapy","oncologic-surgery","electrochemotherapy","cryotherapy"],address:{street:"C. Gabriel Mancera 709, Col. Del Valle Centro, Benito Ju\xe1rez",locality:"Mexico City",region:"Ciudad de M\xe9xico",postalCode:"03100",country:"Mexico"},phone:"+52 55 3125 8092",phoneE164:"+525531258092",email:"info@petsoncology.mx",openingHours:"Tuesday to Friday, 9:00–18:00 \xb7 Saturday and Sunday, 9:00–15:00",openingHoursSpec:["Tu-Fr 09:00-18:00","Sa-Su 09:00-15:00"],geo:null,summary:"Comprehensive veterinary cancer center in Colonia Del Valle Centro, Mexico City.",description:["Pets Oncology is a comprehensive veterinary cancer center in Del Valle Centro, in the Benito Ju\xe1rez borough of Mexico City. It handles diagnosis, staging and treatment of cancer in dogs and cats in one location.","Services include oncology consultation, cytology and histopathology, diagnostic imaging, chemotherapy, oncologic surgery, electrochemotherapy and cryotherapy. The presence of both electrochemotherapy and cryotherapy gives the team more than one local option for tumours that are accessible but where wide surgical margins are difficult to achieve.","The center is open Tuesday to Friday from 9:00 to 18:00 and on Saturday and Sunday from 9:00 to 15:00 — including both weekend days, which is unusual for specialist veterinary care and makes the center reachable for owners who cannot travel on weekdays.","Radiotherapy is not delivered at this location. Within Mexico, Orbit operates radiotherapy at the Guadalajara center, and cases that require it are referred there.","Pets Oncology follows the unified medical, technical and safety standards applied across all Orbit centers, and works alongside referring veterinarians across Mexico City."],distinction:null,todo:["Verified GPS coordinates.","Confirm the center is closed on Mondays (the published hours list Tuesday to Sunday).","Confirm that radiotherapy referrals from Mexico City go to Guadalajara.","Facility photography."]},{slug:"vcc-mexico-city",name:"VCC Veterinary Cancer Center",localName:"VCC – Veterinary Cancer Center",city:"Mexico City",neighbourhood:"Ver\xf3nica Anz\xfares",country:"Mexico",countryCode:"MX",countrySlug:"mexico",type:"comprehensive",status:"operating",website:"https://veterinarycancercenter.mx",socialProfiles:["https://www.instagram.com/veterinarycancercenter.cdmx/"],mapPoint:{lat:19.4413,lng:-99.177},mapNudge:{dx:13,dy:-6},logo:{src:"/images/centers/logos/vcc-mexico-city.svg",width:261,height:67},services:["oncology-consultation","cytology-histopathology","diagnostic-imaging","chemotherapy","oncologic-surgery","electrochemotherapy"],address:{street:"Av. Ej\xe9rcito Nacional Mexicano 156, Ver\xf3nica Anz\xfares, Miguel Hidalgo",locality:"Mexico City",region:"Ciudad de M\xe9xico",postalCode:"11590",country:"Mexico"},phone:"+52 55 4899 0651",phoneE164:"+525548990651",email:"info@veterinarycancercenter.mx",openingHours:"Monday to Saturday, 10:00–19:00, by appointment",openingHoursSpec:["Mo-Sa 10:00-19:00"],geo:null,summary:"Specialist veterinary oncology center in Ver\xf3nica Anz\xfares, Mexico City.",description:["VCC – Veterinary Cancer Center is a specialist veterinary oncology center in Ver\xf3nica Anz\xfares, in the Miguel Hidalgo borough of Mexico City. It is the second Orbit center in the city, alongside Pets Oncology in Del Valle, and it works entirely on cancer in dogs and cats rather than as a general practice with an oncology service attached.","The center covers oncology consultation, cytology and histopathology, diagnostic imaging, veterinary chemotherapy, oncologic surgery and electrochemotherapy. Having diagnosis and treatment in the same place matters more than it sounds: most decisions in veterinary oncology depend on knowing exactly which tumour type is present, and doing that work in-house removes the most common source of delay between a suspicious finding and a plan.","Electrochemotherapy — a chemotherapy agent combined with controlled electrical pulses that increase its uptake by tumour cells — is available on site, and is one of the options considered for tumours that are accessible but difficult to remove with clean margins.","The center is led by Dr. Alejandro Cervantes, who its site describes as having more than ten years dedicated exclusively to veterinary oncology. Consultations are by appointment, Monday to Saturday.","Radiotherapy is not delivered at this location. Within the Orbit network in Mexico it is available at COV Guadalajara, and cases that require it are referred there."],distinction:null,todo:["Verified GPS coordinates.","Facility photography.","Confirm that radiotherapy referrals from this center go to Guadalajara.","Confirm how the center should be named in Orbit’s directory — its own site uses “VCC – Veterinary Cancer Center”."]},{slug:"san-jose-costa-rica",name:"CORV Costa Rica",localName:"Cl\xednica de Oncolog\xeda y Radioterapia Veterinaria Costa Rica",city:"San Jos\xe9",country:"Costa Rica",countryCode:"CR",countrySlug:"costa-rica",type:"comprehensive-radiotherapy",status:"operating",website:"https://corvcostarica.com",mapPoint:{lat:9.9281,lng:-84.0907},logo:{src:"/images/centers/logos/san-jose-costa-rica.webp",width:96,height:96},services:["oncology-consultation","cytology-histopathology","diagnostic-imaging","chemotherapy","oncologic-surgery","radiotherapy"],address:{street:"100 m norte de la Corporaci\xf3n Font, Las \xc1nimas",locality:"San Jos\xe9",region:null,postalCode:null,country:"Costa Rica",note:"Costa Rican addresses are given by reference point rather than street number."},phone:"+506 7008-6748",phoneE164:"+50670086748",email:"info@corvcostarica.com",openingHours:"Monday to Saturday, 9:00–18:00",openingHoursSpec:["Mo-Sa 09:00-18:00"],geo:null,summary:"The only center with a veterinary linear accelerator in Costa Rica and Central America.",description:["The Cl\xednica de Oncolog\xeda y Radioterapia Veterinaria Costa Rica is, in the center’s own words, the only center with a veterinary linear accelerator in Costa Rica and Central America. For pet owners across the region, it is the nearest option for radiotherapy without an international flight.","It is a comprehensive cancer center. Oncology consultation, diagnostic imaging, cytology and histopathology, oncologic surgery, chemotherapy and veterinary radiotherapy are all available on site, so the decision about which treatment fits a given tumour is made by the team that can deliver any of them.","A linear accelerator is the same class of equipment used in human radiation oncology: it produces a controlled beam that is shaped to the tumour and delivered in planned fractions. Sessions are outpatient — the patient is positioned, treated in minutes, and goes home the same day.","The center is open Monday to Saturday from 9:00 to 18:00 and works with referring veterinarians throughout Costa Rica and Central America. It applies the unified medical, technical and safety standards used across every Orbit center."],distinction:"The only center with a veterinary linear accelerator in Costa Rica and Central America.",todo:["Verified GPS coordinates — particularly important here, since the published address uses a reference point rather than a street number.","Canton and district, for a structured address.","Facility and linear accelerator photography."]},{slug:"santiago-chile",name:"COV Santiago",localName:"Centro Oncol\xf3gico Veterinario Santiago",city:"Santiago",country:"Chile",countryCode:"CL",countrySlug:"chile",type:"comprehensive-radiotherapy",status:"operating",website:"https://covsantiago.cl",mapPoint:{lat:-33.4569,lng:-70.5977},logo:{src:"/images/centers/logos/santiago-chile.svg",width:677,height:230},services:["oncology-consultation","cytology-histopathology","diagnostic-imaging","chemotherapy","oncologic-surgery","electrochemotherapy","radiotherapy"],address:{street:"Antonio Varas 2130, \xd1u\xf1oa",locality:"Santiago",region:"Regi\xf3n Metropolitana",postalCode:null,country:"Chile"},phone:"+56 9 7568-2353",phoneE164:"+56975682353",email:"info@covsantiago.cl",openingHours:null,openingHoursSpec:null,geo:null,summary:"Comprehensive veterinary cancer center with radiotherapy in \xd1u\xf1oa, Santiago.",description:["The Centro Oncol\xf3gico Veterinario Santiago is a comprehensive veterinary cancer center in \xd1u\xf1oa, covering the full pathway from first consultation to treatment for dogs and cats in the Santiago Metropolitan Region.","Available on site: oncology consultation, cytology and histopathology, diagnostic imaging, veterinary chemotherapy, oncologic surgery, electrochemotherapy and veterinary radiotherapy. Because all of them are under one roof, the treatment decision is not constrained by what the building can do — the team can weigh surgery, systemic treatment, a local technique and radiation against each other on clinical grounds.","Radiotherapy is planned individually for each patient using imaging that maps the tumour and the healthy tissue around it, then delivered in outpatient fractions. The animal is positioned, treated, and goes home the same day.","The center applies the unified medical, technical and safety standards used across the Orbit network and works with referring veterinarians throughout Chile, staying alongside the primary veterinarian rather than taking over the animal’s general care."],distinction:null,todo:["Opening hours.","Verified GPS coordinates.","Postal code for the structured address.","Facility and linear accelerator photography."]},{slug:"buenos-aires-argentina",name:"Pet Salud",localName:"Pet Salud | Oncolog\xeda Radiante Veterinaria",city:"Buenos Aires",country:"Argentina",countryCode:"AR",countrySlug:"argentina",type:"radiation-oncology",status:"operating",website:"https://pet-salud.com.ar",mapPoint:{lat:-34.6037,lng:-58.3816},logo:{src:"/images/centers/logos/buenos-aires-argentina.webp",width:288,height:96},services:["radiotherapy","oncology-consultation"],address:{street:"Tinogasta 5428",locality:"Ciudad Aut\xf3noma de Buenos Aires",region:null,postalCode:null,country:"Argentina"},phone:"+54 9 11 7826-3477",phoneE164:"+5491178263477",email:"info@pet-salud.com.ar",openingHours:null,openingHoursSpec:null,geo:null,summary:"Veterinary radiation oncology in Buenos Aires.",description:["Pet Salud is Orbit’s veterinary radiation oncology center in the Ciudad Aut\xf3noma de Buenos Aires. It gave the network its name: Pet Salud is the organisation through which Orbit’s team has built veterinary cancer care across Latin America since 2020.","The center delivers radiotherapy for cancer in dogs and cats, planned individually for each patient. Consultations are multidisciplinary, bringing together veterinarians and radiotherapy specialists to define the plan, and the team monitors the patient through the course of treatment.","Alongside oncologic radiotherapy, the center offers radiotherapy for pain — a palliative use of radiation aimed at reducing pain caused by a tumour rather than at controlling the tumour itself. It is an option worth knowing about for patients where the goal of treatment is comfort.","Sessions are outpatient. The center works with referring veterinarians across Buenos Aires and applies the unified medical, technical and safety standards used at every Orbit center — the same standards derived from four decades of human radiation oncology practice."],distinction:null,todo:["Opening hours.","Verified GPS coordinates.","Neighbourhood and postal code for the structured address.","Facility and linear accelerator photography."]},{slug:"malaga-spain",name:"Pet Salud M\xe1laga",localName:"Pet Salud M\xe1laga | Radioterapia Veterinaria",city:"M\xe1laga",country:"Spain",countryCode:"ES",countrySlug:"spain",type:"radiation-oncology",status:"operating",website:"https://petsaludmalaga.es",mapPoint:{lat:36.6636,lng:-4.5606},logo:{src:"/images/centers/logos/malaga-spain.webp",width:100,height:96},services:["radiotherapy","oncology-consultation"],address:{street:"Parque Empresarial Laurotorre, C. Crianza, 25",locality:"Alhaur\xedn de la Torre",region:"M\xe1laga",postalCode:"29130",country:"Spain"},phone:"+34 689 49 32 48",phoneE164:"+34689493248",email:"info@petsaludmalaga.es",openingHours:null,openingHoursSpec:null,geo:null,summary:"The only specialist veterinary radiotherapy service in Andalusia.",description:["Pet Salud M\xe1laga is Orbit’s veterinary radiotherapy center in Spain and, in the center’s own words, the only specialist veterinary radiotherapy service in Andalusia. It operates from Alhaur\xedn de la Torre, in the M\xe1laga metropolitan area, and is Orbit’s only European location.","The center treats dogs and cats with both curative and palliative intent. Curative protocols aim at long-term tumour control and are usually delivered in a larger number of smaller fractions; palliative protocols use fewer sessions and are aimed at reducing the discomfort a tumour causes. Which applies depends on the tumour type, its location and its stage, and is decided case by case.","Each plan starts from imaging that maps the tumour and the healthy structures around it. Treatment is non-invasive and delivered on an outpatient basis, and the team follows the patient through the course and afterwards.","For referring veterinarians across Andalusia, the center provides the radiotherapy component while the primary veterinarian keeps managing the animal’s overall care. It applies the unified medical, technical and safety standards used across the Orbit network."],distinction:"The only specialist veterinary radiotherapy service in Andalusia.",todo:["Opening hours.","Verified GPS coordinates.","Facility and linear accelerator photography."]}];o.map(e=>e.slug);let i={name:"Orbit Veterinary Oncology",shortName:"Orbit",legalName:"Orbit Veterinary Oncology",tagline:"Human-Grade Oncology, For Our Pets.",email:"hello@orbitonco.com",phone:null,socialProfiles:[],foundingDate:"2020"},n=[{label:"Our Veterinary Centers",href:"/our-centers/",hasCentersDropdown:!0},{label:"About Us",href:"/about-us/"},{label:"Contact Us",href:"/contact-us/"}],r={label:"Get in touch",href:"/contact-us/"},s=o.map(e=>({slug:e.slug,name:e.name,href:e.website,meta:e.neighbourhood?"".concat(e.neighbourhood,", ").concat(e.city):"".concat(e.city,", ").concat(e.country),status:e.status}))}}]);